package za.co.loopmanager;
import org.json.JSONObject;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={30,35})
public class ManagedUpdatesTest {
 private JSONObject fixture()throws Exception{return new JSONObject().put("kind","client_update").put("device_id","this-phone").put("server_time",10000).put("expires",13600).put("available",true).put("package_name","za.co.loopmanager").put("version_code",24).put("min_sdk",30).put("bytes",2048).put("apk_url","https://ourxezawbfclmhbggskv.supabase.co/storage/v1/object/public/loop-phone-installers/client-0.17.0-"+"a".repeat(64)+".apk").put("apk_sha256","A".repeat(43));}
 @Test public void updateManifestMustBeFreshAndBoundToThisInstallation()throws Exception{ManagedUpdates.validate(fixture(),"this-phone",10005,23);for(String id:new String[]{"another-phone",""}){try{ManagedUpdates.validate(fixture(),id,10005,23);fail();}catch(SecurityException expected){}}for(long time:new long[]{-1,9000,14000}){try{ManagedUpdates.validate(fixture(),"this-phone",time,23);fail();}catch(SecurityException expected){}}}
 @Test public void cannotDowngradeOrInstallOtherAppOrUntrustedStorage()throws Exception{for(JSONObject m:new JSONObject[]{fixture().put("version_code",23),fixture().put("package_name","another.app"),fixture().put("bytes",40*1024*1024),fixture().put("apk_url","https://evil.example/client.apk"),fixture().put("apk_sha256","bad")}){try{ManagedUpdates.validate(m,"this-phone",10005,23);fail(m.toString());}catch(SecurityException expected){}}assertFalse(ManagedUpdates.trustedUrl("https://ourxezawbfclmhbggskv.supabase.co.evil.example/storage/client.apk"));}
}
